const REGIONAL_SYNONYM_REPLACEMENTS = [
  ['雪梨', '悉尼'],
  ['紐西蘭', '新西兰'],
  ['纽西兰', '新西兰'],
  ['澳洲', '澳大利亚'],
  ['南韓', '韩国'],
  ['南韩', '韩国'],
  ['沙烏地阿拉伯', '沙特阿拉伯'],
  ['沙乌地阿拉伯', '沙特阿拉伯'],
  ['阿拉伯聯合大公國', '阿联酋'],
  ['阿拉伯联合大公国', '阿联酋'],
  ['奈及利亞', '尼日利亚'],
  ['奈及利亚', '尼日利亚'],
  ['肯亞', '肯尼亚'],
  ['肯亚', '肯尼亚'],
  ['衣索比亞', '埃塞俄比亚'],
  ['衣索比亚', '埃塞俄比亚'],
  ['迦納', '加纳'],
  ['迦纳', '加纳'],
  ['通貨膨脹', '通货膨胀'],
  ['通膨', '通胀'],
  ['加值稅', '增值税'],
  ['加值税', '增值税'],
  ['營所稅', '企业所得税'],
  ['營利事業所得稅', '企业所得税'],
  ['綜所稅', '个人所得税'],
  ['綜合所得稅', '个人所得税'],
  ['樓價', '房价'],
  ['楼价', '房价']
];

export function cjkToSimplified(str) {
  if (!str || typeof str !== 'string') return '';
  let s = str;
  for (let i = 0; i < REGIONAL_SYNONYM_REPLACEMENTS.length; i++) {
    const [from, to] = REGIONAL_SYNONYM_REPLACEMENTS[i];
    if (s.includes(from)) {
      s = s.split(from).join(to);
    }
  }
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    out += T2S_CHAR_MAP[ch] || ch;
  }
  return out;
}

export function normalizeSearchInput(rawInput) {
  if (rawInput === null || rawInput === undefined) {
    return {
      raw: '',
      trimmed: '',
      lower: '',
      cleanPunct: '',
      compact: '',
      simplified: '',
      simplifiedCompact: '',
      tokens: [],
      isEmpty: true,
      hasCjk: false
    };
  }

  const raw = String(rawInput);
  const trimmed = raw.replace(/[\u3000\s]+/g, ' ').trim();
  if (!trimmed) {
    return {
      raw,
      trimmed: '',
      lower: '',
      cleanPunct: '',
      compact: '',
      simplified: '',
      simplifiedCompact: '',
      tokens: [],
      isEmpty: true,
      hasCjk: false
    };
  }

  const lower = trimmed.toLowerCase();
  const noDots = lower.replace(/\.+/g, '');
  const cleanPunct = noDots
    .replace(/[\-_\/·•,;:!?'\"()（）\[\]【】《》「」『』]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const compact = cleanPunct.replace(/\s+/g, '');
  const simplified = cjkToSimplified(cleanPunct);
  const simplifiedCompact = simplified.replace(/\s+/g, '');
  const hasCjk = /[\u4e00-\u9fff]/.test(trimmed);
  const tokens = cleanPunct ? cleanPunct.split(' ').filter(Boolean) : [];

  return {
    raw,
    trimmed,
    lower,
    cleanPunct,
    compact,
    simplified,
    simplifiedCompact,
    tokens,
    isEmpty: false,
    hasCjk
  };
}

export default {
  cjkToSimplified,
  normalizeSearchInput
};
